 private void initVoice(String id){
  stop();ready=false;int generation=++voiceEpoch;if(voice!=null){voice.shutdown();voice=null;}
  final List<String> names=new ArrayList<>(),ids=new ArrayList<>();names.add("Genny local incluida · sin TTS del sistema");ids.add("genny");names.add("Motor predeterminado de Android");ids.add("");
  for(android.content.pm.ResolveInfo info:getPackageManager().queryIntentServices(new Intent(TextToSpeech.Engine.INTENT_ACTION_TTS_SERVICE),0)){String name=info.serviceInfo.packageName;if(!ids.contains(name)){names.add(info.loadLabel(getPackageManager()).toString());ids.add(name);}}
  if(!ids.contains(id))id="genny";engineId=id;engine.setOnItemSelectedListener(null);engine.setAdapter(new ArrayAdapter<>(this,android.R.layout.simple_spinner_dropdown_item,names));engine.setSelection(ids.indexOf(id));
  engine.setOnItemSelectedListener(new android.widget.AdapterView.OnItemSelectedListener(){public void onNothingSelected(android.widget.AdapterView<?> parent){}public void onItemSelected(android.widget.AdapterView<?> parent,View view,int index,long item){String next=ids.get(index);if(!next.equals(engineId)){engineId=next;getSharedPreferences("preferences",MODE_PRIVATE).edit().putString("mathEngine",next).apply();initVoice(next);}}});
  if(id.equals("genny")){say("Voz Genny local preparada. Las palabras fuera del banco se deletrean.");return;}
  voice=new TextToSpeech(this,code->main.post(()->{if(closed||generation!=voiceEpoch)return;ready=code==TextToSpeech.SUCCESS;if(ready){ready=voice.setLanguage(new Locale("es"))>=0;voice.setSpeechRate(speechRate);}if(!ready)say("El TTS elegido no está disponible en español. Se usará Genny como respaldo.");}),id.isEmpty()?null:id);
 }
 private EditText edit(String label,String value){text(label);EditText e=new EditText(this);e.setContentDescription(label);e.setText(value);e.setSingleLine(true);body.addView(e);return e;}
 private void text(String s){TextView t=new TextView(this);t.setText(s);t.setTextSize(17);body.addView(t);}
 private void button(String s,Runnable action){Button b=new Button(this);b.setText(s);b.setMinHeight(dp(52));b.setOnClickListener(v->{try{if(learn!=null&&learn.isChecked()&&!s.equals("Detener voz y sonido")&&!s.equals("Volver"))speak("Botón: "+s+". Desactiva Conocer botones para ejecutarlo.");else action.run();}catch(Exception e){say("No se pudo completar: "+e.getMessage());}});body.addView(b);}
 private Spinner spinner(String label,String[] values,java.util.function.IntConsumer change){text(label);Spinner s=new Spinner(this);s.setContentDescription(label);s.setAdapter(new ArrayAdapter<>(this,android.R.layout.simple_spinner_dropdown_item,values));s.setOnItemSelectedListener(new android.widget.AdapterView.OnItemSelectedListener(){public void onNothingSelected(android.widget.AdapterView<?> p){}public void onItemSelected(android.widget.AdapterView<?> p,View v,int n,long id){s.setContentDescription(label+": "+p.getItemAtPosition(n));change.accept(n);}});body.addView(s);return s;}
 private void prepare(){try{MathLesson next=new MathLesson(expression.getText().toString());stop();prepareTeaching(next);lesson=next;preparedInput=expression.getText().toString();if(history!=null){if(!histories.contains(lesson.expression)){histories.add(0,lesson.expression);if(histories.size()>20)histories.remove(20);}history.setAdapter(new ArrayAdapter<>(this,android.R.layout.simple_spinner_dropdown_item,histories));history.setSelection(histories.indexOf(lesson.expression));}position=0;if(display!=null){display.setText(lesson.grid);display.setContentDescription("Operación: "+lesson.reading+". Resultado: "+MathAdvanced.resultSpeech(lesson.result));refresh();}say("Ejercicio preparado. "+lesson.steps.size()+" pasos. Elige qué deseas leer.");}catch(Exception e){say("La expresión no se cambió: "+e.getMessage());}}
 private void refresh(){if(selection==null||mode==null)return;int n=mode.getSelectedItemPosition();items=teaching.readings.get(MathTeaching.KEYS[n]);position=Math.max(0,Math.min(position,items.size()-1));String[] labels=new String[items.size()];for(int i=0;i<labels.length;i++)labels[i]=(i+1)+". "+items.get(i);selection.setAdapter(new ArrayAdapter<>(this,android.R.layout.simple_spinner_dropdown_item,labels));selection.setSelection(position);}
 private void move(int delta){if(!current())return;int next=position+delta;if(listening!=null&&listening.getSelectedItemPosition()==2){if(!editingKey.isEmpty())saveNote();while(next>=0&&next<items.size()&&!teaching.notes.containsKey(teaching.fragment(mode.getSelectedItemPosition(),next)))next+=delta;if(next<0||next>=items.size()){speak("No hay más anotaciones en esta dirección y este orden de lectura.");return;}}position=Math.max(0,Math.min(items.size()-1,next));selection.setSelection(position);if(listening!=null&&listening.getSelectedItemPosition()==0){stop();status.setAccessibilityLiveRegion(View.ACCESSIBILITY_LIVE_REGION_NONE);say("Fragmento "+(position+1)+" seleccionado. Pulsa Leer o repetir cuando quieras.");}else readItem();}
 private void readItem(){if(!current())return;if(!editingKey.isEmpty())saveNote();String key=teaching.fragment(mode.getSelectedItemPosition(),position),prefix="Fragmento "+(position+1)+" de "+items.size()+". ";int policy=listening==null?0:listening.getSelectedItemPosition();speak(prefix+(policy==2?teaching.note(key,0)+". "+teaching.note(key,1):items.get(position)+(policy==1&&teaching.notes.containsKey(key)?". Nota: "+teaching.note(key,0):"")));}
 private int dp(int n){return Math.round(n*getResources().getDisplayMetrics().density);}private boolean current(){if(!expression.getText().toString().equals(preparedInput)){say("Hay cambios pendientes. Pulsa Preparar expresión antes de leer o guardar.");return false;}return true;}private void readMath(String s){if(current())speak(s);}private void say(String s){if(status!=null)status.setText(s);if(fullStatus!=null){fullStatus.setAccessibilityLiveRegion(narration!=null&&narration.isChecked()?View.ACCESSIBILITY_LIVE_REGION_NONE:View.ACCESSIBILITY_LIVE_REGION_POLITE);fullStatus.setText(s);}}
 private void speak(String s){stop();status.setAccessibilityLiveRegion(narration!=null&&narration.isChecked()?View.ACCESSIBILITY_LIVE_REGION_NONE:View.ACCESSIBILITY_LIVE_REGION_POLITE);say(s);if(narration!=null&&narration.isChecked()){s=MathSpeech.normalize(s);if(engineId.equals("genny")||!ready){genny.speak(s,speechRate,null,()->say("No se pudo reproducir Genny. La explicación queda disponible en texto."));return;}for(int start=0;start<s.length();start+=2800)voice.speak(s.substring(start,Math.min(s.length(),start+2800)),start==0?TextToSpeech.QUEUE_FLUSH:TextToSpeech.QUEUE_ADD,null,"math-"+voiceEpoch+"-"+start);}}
 private void stop(){if(genny!=null)genny.stop();scanEpoch++;contactMap.reset();previousContact=null;if(audio!=null)audio.stop();if(voice!=null)voice.stop();}
 private void trace(int index){showPoint(MathLesson.trace(planeKind,index));}private void showPoint(Map<String,Object> p){x=((Number)p.get("x")).doubleValue();y=((Number)p.get("y")).doubleValue();traceIndex=Math.max(0,((Number)p.get("index")).intValue());updatePoint();speak((String)p.get("description"));}private double coordinate(EditText e){double v=Double.parseDouble(e.getText().toString().trim().replace(',','.'));if(!Double.isFinite(v)||Math.abs(v)>5)throw new IllegalArgumentException("Las coordenadas deben estar entre menos cinco y cinco.");return v;}
 private void updatePoint(){xField.setText(Double.toString(x));yField.setText(Double.toString(y));canvasPointer=MathLesson.point(x,y);canvas.invalidate();if(fullPlane!=null)fullPlane.invalidate();}
 private void shift(int dx,int dy){x=Math.max(-5,Math.min(5,x+dx));y=Math.max(-5,Math.min(5,y+dy));updatePoint();speak(MathLesson.at(planeKind,x,y));}
