  surfaceChoice=spinner("Respuesta al dedo",new String[]{"Contorno","Relleno de regiones","Negativo: exterior sonoro"},n->{stop();touchSurface=n;getSharedPreferences("preferences",MODE_PRIVATE).edit().putInt("surface",n).apply();});surfaceChoice.setSelection(touchSurface);
  filterChoice=spinner("Componentes explorados",new String[]{"Todo: ejes y figura","Sólo figura","Sólo ejes"},n->{stop();touchFilter=n;scanSection=-1;refreshMathElements();});
  airChoice=new CheckBox(this);airChoice.setText("Aire espacial tenue en el vacío y proximidad a bordes");airChoice.setChecked(mathAir);airChoice.setOnCheckedChangeListener((b,on)->{mathAir=on;getSharedPreferences("preferences",MODE_PRIVATE).edit().putBoolean("air",on).apply();});body.addView(airChoice);
  hapticChoice=new CheckBox(this);hapticChoice.setText("Vibración en el marco, cruces y cambios de contacto");hapticChoice.setChecked(mathHaptics);hapticChoice.setOnCheckedChangeListener((b,on)->{mathHaptics=on;getSharedPreferences("preferences",MODE_PRIVATE).edit().putBoolean("haptics",on).apply();});body.addView(hapticChoice);
  text("Tolerancia de contacto, de seis a treinta y cinco unidades");SeekBar tolerance=new SeekBar(this);tolerance.setMax(29);tolerance.setProgress((int)mathTolerance-6);tolerance.setContentDescription("Tolerancia de contacto: "+(int)mathTolerance);tolerance.setOnSeekBarChangeListener(new SeekBar.OnSeekBarChangeListener(){public void onStartTrackingTouch(SeekBar b){}public void onStopTrackingTouch(SeekBar b){}public void onProgressChanged(SeekBar b,int value,boolean user){if(user){mathTolerance=value+6;b.setContentDescription("Tolerancia de contacto: "+(int)mathTolerance);getSharedPreferences("preferences",MODE_PRIVATE).edit().putFloat("tolerance",(float)mathTolerance).apply();}}});body.addView(tolerance);
  spinner("Granularidad de exploración",new String[]{"Bordes y curvas","Vértices","Regiones"},n->{mathLevel=n;mathElement=0;refreshMathElements();});elementChoice=spinner("Elemento del plano",new String[]{"Preparando elementos"},n->{mathElement=n;});button("Elemento anterior del plano",()->moveMathElement(-1));button("Escuchar elemento del plano",this::playMathElement);button("Elemento siguiente del plano",()->moveMathElement(1));button("Audiodescribir elemento del plano",()->{List<Geometry.Element> elements=mathElements();if(elements.isEmpty()){say("No hay elementos de este tipo con el filtro actual.");return;}speak(MathExploration.element(elements.get(Math.min(mathElement,elements.size()-1)),mathLevel));});
  scanChoice=spinner("Barrido sonoro del plano",new String[]{"Filas","Columnas","Cuadrantes","Relleno de silueta","Contorno desde referencia"},n->scanSection=-1);scanOrigin=spinner("Inicio del barrido",new String[]{"Superior izquierda","Superior derecha","Inferior derecha","Inferior izquierda","Último punto explorado"},n->scanSection=-1);spinner("Separación del barrido",new String[]{"Fina: veinte unidades","Media: cuarenta unidades","Amplia: sesenta unidades"},n->{scanSpacing=new int[]{20,40,60}[n];scanSection=-1;}).setSelection(1);
  invertScan=new CheckBox(this);invertScan.setText("Invertir contraste sonoro del barrido");body.addView(invertScan);button("Leer barrido completo",()->mathScan(-1));button("Leer siguiente fila o sección",()->mathScan(scanSection+1));button("Volver a primera sección del barrido",()->mathScan(0));button("Pausar recorrido matemático",()->mathTransport("pause"));button("Continuar recorrido matemático",()->mathTransport("resume"));button("Retroceder cinco segundos y pausar",()->mathTransport("back"));button("Guardar marcador del recorrido",()->mathTransport("mark"));button("Volver al marcador del recorrido",()->mathTransport("return"));button("Repetir últimos cinco segundos",()->mathTransport("fragment"));refreshMathElements();
