 private List<Geometry.Element> mathElements(){return MathExploration.geometry(planeKind,touchFilter).elements(mathLevel);}
 private void refreshMathElements(){scanSection=-1;contactMap.reset();previousContact=null;if(canvas!=null)canvas.invalidate();if(fullPlane!=null)fullPlane.invalidate();if(elementChoice==null)return;List<Geometry.Element> elements=mathElements();mathElement=Math.min(mathElement,Math.max(0,elements.size()-1));List<String> labels=new ArrayList<>();for(int i=0;i<elements.size();i++)labels.add((i+1)+" de "+elements.size()+". "+MathExploration.element(elements.get(i),mathLevel));if(labels.isEmpty())labels.add("Sin elementos de este tipo. Cambia granularidad o filtro.");elementChoice.setAdapter(new ArrayAdapter<>(this,android.R.layout.simple_spinner_dropdown_item,labels));elementChoice.setSelection(mathElement);elementChoice.setContentDescription("Elemento del plano: "+labels.get(mathElement));}
 private void moveMathElement(int delta){List<Geometry.Element> elements=mathElements();if(elements.isEmpty()){say("No hay elementos de este tipo con el filtro actual.");return;}mathElement=Math.floorMod(mathElement+delta,elements.size());elementChoice.setSelection(mathElement);playMathElement();}
 private void playMathElement(){List<Geometry.Element> elements=mathElements();if(elements.isEmpty()){say("No hay elementos de este tipo con el filtro actual.");return;}Geometry.Element e=elements.get(Math.min(mathElement,elements.size()-1));canvasPointer=e.center();canvas.invalidate();if(fullPlane!=null)fullPlane.invalidate();playMathProgram(Sound.Program.element(e,mathLevel,sound),MathExploration.element(e,mathLevel));}
 private void playMathProgram(Sound.Program program,String description){stop();final int epoch=scanEpoch;say(description);audio.play(program,()->main.post(()->{if(!closed&&epoch==scanEpoch)say("Recorrido terminado.");}));}
 private void mathTransport(String command){scanEpoch++;if(voice!=null)voice.stop();audio.control(command,message->main.post(()->{if(!closed)say(message);}));}
 private void mathScan(int section){stop();final int epoch=scanEpoch,kind=planeKind,filter=touchFilter,mode=scanChoice.getSelectedItemPosition(),spacing=scanSpacing;int origin=scanOrigin.getSelectedItemPosition();final Geometry.Point start=origin==4?canvasPointer:new Geometry.Point(origin==1||origin==2?600:0,origin>=2?450:0);final boolean invert=invertScan.isChecked();final Sound.Settings settings=sound.copy();say("Preparando barrido sonoro…");scanWorker.execute(()->{try{MathExploration.Scan result=MathExploration.scan(kind,filter,settings,mode,start,spacing,section,invert);main.post(()->{if(closed||epoch!=scanEpoch)return;scanSection=section;say(result.description);audio.play(result.program,null);});}catch(Exception e){main.post(()->{if(!closed&&epoch==scanEpoch)say(e.getMessage());});}});}
 private void boundaryVibration(TouchMap.Feedback current){boolean now=current.frame||current.kind.equals("line")||current.kind.equals("vertex")||current.kind.equals("region"),before=previousContact!=null&&(previousContact.frame||previousContact.kind.equals("line")||previousContact.kind.equals("vertex")||previousContact.kind.equals("region"));if(mathHaptics&&(now!=before||previousContact!=null&&(current.inside!=previousContact.inside||current.frame!=previousContact.frame))&&SystemClock.elapsedRealtime()-lastHaptic>220){Vibrator vibrator=(Vibrator)getSystemService(VIBRATOR_SERVICE);if(vibrator!=null&&vibrator.hasVibrator()){lastHaptic=SystemClock.elapsedRealtime();vibrator.vibrate(VibrationEffect.createOneShot(24,VibrationEffect.DEFAULT_AMPLITUDE));}}previousContact=current;}
 private Button canvasButton(String label,Runnable action){Button button=new Button(this);button.setText(label);button.setMinHeight(dp(52));button.setOnClickListener(v->action.run());return button;}
 private void openMathCanvas(){stop();if(canvasDialog!=null&&canvasDialog.isShowing())return;canvasDialog=new Dialog(this,android.R.style.Theme_Material_NoActionBar);LinearLayout layout=new LinearLayout(this);layout.setOrientation(LinearLayout.VERTICAL);layout.setFitsSystemWindows(true);TextView heading=new TextView(this);heading.setText("Lienzo matemático: "+MathLesson.PLANES[planeKind]+". El marco y el vacío también suenan. Atrás vuelve a la lección.");heading.setTextSize(17);layout.addView(heading);fullPlane=new PlaneCanvas();layout.addView(fullPlane,new LinearLayout.LayoutParams(-1,0,1));Spinner modes=new Spinner(this);modes.setAdapter(new ArrayAdapter<>(this,android.R.layout.simple_spinner_dropdown_item,new String[]{"Filas","Columnas","Cuadrantes","Relleno de silueta","Contorno desde referencia"}));modes.setSelection(scanChoice.getSelectedItemPosition());modes.setContentDescription("Barrido sonoro: "+modes.getSelectedItem());modes.setOnItemSelectedListener(new android.widget.AdapterView.OnItemSelectedListener(){public void onNothingSelected(android.widget.AdapterView<?> p){}public void onItemSelected(android.widget.AdapterView<?> p,View v,int n,long id){scanChoice.setSelection(n);modes.setContentDescription("Barrido sonoro: "+p.getItemAtPosition(n));}});layout.addView(modes);fullStatus=new TextView(this);fullStatus.setTextSize(16);fullStatus.setMaxLines(3);fullStatus.setAccessibilityLiveRegion(View.ACCESSIBILITY_LIVE_REGION_POLITE);layout.addView(fullStatus);LinearLayout row=new LinearLayout(this);row.addView(canvasButton("Marco",()->playMathProgram(MathExploration.frame(sound),"Marco completo.")),new LinearLayout.LayoutParams(0,-2,1));row.addView(canvasButton("Centro y esquinas",()->playMathProgram(MathExploration.reference(sound),"Centro y cuatro esquinas.")),new LinearLayout.LayoutParams(0,-2,1));layout.addView(row);LinearLayout scan=new LinearLayout(this);scan.addView(canvasButton("Barrido completo",()->mathScan(-1)),new LinearLayout.LayoutParams(0,-2,1));scan.addView(canvasButton("Siguiente sección",()->mathScan(scanSection+1)),new LinearLayout.LayoutParams(0,-2,1));layout.addView(scan);LinearLayout bottom=new LinearLayout(this);bottom.addView(canvasButton("Detener",this::stop),new LinearLayout.LayoutParams(0,-2,1));bottom.addView(canvasButton("Volver a la lección",()->canvasDialog.dismiss()),new LinearLayout.LayoutParams(0,-2,1));layout.addView(bottom);canvasDialog.setContentView(layout);canvasDialog.setOnDismissListener(d->{stop();fullPlane=null;fullStatus=null;canvasDialog=null;});canvasDialog.show();canvasDialog.getWindow().setLayout(-1,-1);}
 private void buildTeaching(){
  text("Lección y anotaciones. Las notas son textos aportados por quien prepara la lección; no son verificaciones matemáticas. Guarda la lección FAO para enviarla y devolver comentarios.");
  button("Probar ecuación con notas del profesor",()->teachingExample("ecuacion-con-anotaciones.fao"));button("Probar fracciones con notas del profesor",()->teachingExample("fracciones-con-anotaciones.fao"));
  listening=spinner("Cómo escuchar la lección",new String[]{"Exploración libre: notas a petición","Entrenamiento guiado: fragmento y nombre de nota","Repaso de notas: avance manual"},n->{stop();announce.setChecked(false);announce.setEnabled(n==1);});
  lessonTitle=edit("Título de la lección",teaching.title);lessonTitle.setFilters(new android.text.InputFilter[]{new android.text.InputFilter.LengthFilter(160)});lessonFeedback=edit("Alternativas o comentarios generales para devolver al profesor","");lessonFeedback.setSingleLine(false);lessonFeedback.setFilters(new android.text.InputFilter[]{new android.text.InputFilter.LengthFilter(6000)});
  noteTarget=spinner("Elemento que quieres anotar o consultar",new String[]{"Fragmento seleccionado","Vista general del plano","Punto actual del plano"},n->{});
  button("Editar anotación del elemento elegido",this::editNote);noteAnchor=new TextView(this);noteAnchor.setText("Sin anotación en edición");body.addView(noteAnchor);
  noteName=edit("Nombre breve de la anotación","");noteName.setFilters(new android.text.InputFilter[]{new android.text.InputFilter.LengthFilter(160)});noteDescription=edit("Explicación de la anotación","");noteHint=edit("Pista de la anotación","");noteComment=edit("Respuesta, duda o propuesta sobre este elemento","");for(EditText e:new EditText[]{noteDescription,noteHint,noteComment}){e.setSingleLine(false);e.setFilters(new android.text.InputFilter[]{new android.text.InputFilter.LengthFilter(3000)});}
  button("Guardar anotación en la lección",()->{saveNote();say("Anotación guardada en memoria. Guarda la lección FAO para conservarla al cerrar.");});button("Leer nombre de la nota",()->readNote(0));button("Leer explicación de la nota",()->readNote(1));button("Pedir pista de la nota",()->readNote(2));button("Leer comentario del elemento",()->readNote(3));button("Eliminar anotación elegida",()->{String key=targetKey();teaching.notes.remove(key);if(editingKey.equals(key)){editingKey="";clearNote();}say("Anotación eliminada de esta lección.");});
  button("Guardar lección FAO para compartir",()->{if(!current())return;captureTeaching();export(teaching.json(),"leccion-formas.fao","application/json");});button("Abrir lección FAO",()->{Intent i=new Intent(Intent.ACTION_OPEN_DOCUMENT);i.addCategory(Intent.CATEGORY_OPENABLE);i.setType("*/*");startActivityForResult(i,503);});
 }
 private String targetKey(){if(!current())throw new IllegalArgumentException("Prepara la expresión antes de editar notas.");int n=noteTarget.getSelectedItemPosition();return n==0?teaching.fragment(mode.getSelectedItemPosition(),position):n==1?"plane:"+planeKind:MathTeaching.pointTarget(planeKind,x,y);}
 private void clearNote(){if(noteName==null)return;noteName.setText("");noteDescription.setText("");noteHint.setText("");noteComment.setText("");noteAnchor.setText("Sin anotación en edición");}
 private void saveNote(){if(editingKey.isEmpty())throw new IllegalArgumentException("Primero elige Editar anotación del elemento elegido.");teaching.put(editingKey,noteName.getText().toString(),noteDescription.getText().toString(),noteHint.getText().toString(),noteComment.getText().toString());}
 private void editNote(){if(!editingKey.isEmpty())saveNote();editingKey=targetKey();Map<String,Object> n=teaching.notes.get(editingKey);EditText[] fields={noteName,noteDescription,noteHint,noteComment};String[] keys={"name","description","hint","comment"};for(int i=0;i<fields.length;i++)fields[i].setText(n==null?"":(String)n.get(keys[i]));noteAnchor.setText("Editando "+teaching.describeTarget(editingKey)+". La nota seguirá vinculada a este destino aunque te muevas.");say("Anotación lista para editar.");}
 private void readNote(int level){if(!editingKey.isEmpty())saveNote();speak(teaching.note(targetKey(),level));}
 private void captureTeaching(){if(lessonTitle==null)return;if(!editingKey.isEmpty())saveNote();teaching.title=lessonTitle.getText().toString();teaching.feedback=lessonFeedback.getText().toString();teaching.mode=mode.getSelectedItemPosition();teaching.position=position;teaching.plane=planeKind;teaching.x=x;teaching.y=y;}
 private void prepareTeaching(MathLesson next){if(teaching.lesson.expression.equals(next.expression))return;captureTeaching();teachingHistory.put(teaching.lesson.expression,teaching);teaching=teachingHistory.containsKey(next.expression)?teachingHistory.get(next.expression):new MathTeaching(next);if(teachingHistory.size()>20)teachingHistory.remove(teachingHistory.keySet().iterator().next());editingKey="";clearNote();if(lessonTitle!=null){lessonTitle.setText(teaching.title);lessonFeedback.setText(teaching.feedback);}}
 private void openTeaching(String json){MathTeaching next=MathTeaching.load(json);captureTeaching();teachingHistory.put(teaching.lesson.expression,teaching);if(teachingHistory.size()>20)teachingHistory.remove(teachingHistory.keySet().iterator().next());teaching=next;editingKey="";clearNote();expression.setText(next.lesson.expression);prepare();lessonTitle.setText(next.title);lessonFeedback.setText(next.feedback);planeKind=next.plane;planeSelect.setSelection(planeKind);x=next.x;y=next.y;mode.setSelection(next.mode);position=next.position;refresh();updatePoint();stop();say("Lección abierta. Voz y modo de escucha conservan tus preferencias. Las etapas y notas son contenido del autor.");}
 private void teachingExample(String name){try(InputStream in=getAssets().open("teaching/"+name);ByteArrayOutputStream out=new ByteArrayOutputStream()){byte[] buffer=new byte[4096];int n;while((n=in.read(buffer))!=-1){if(out.size()+n>MathTeaching.MAX_BYTES)throw new IOException("Lección demasiado grande.");out.write(buffer,0,n);}openTeaching(new String(out.toByteArray(),StandardCharsets.UTF_8));}catch(Exception e){say("No se pudo abrir el ejemplo: "+e.getMessage());}}
 private void export(String data,String name,String mime){if(!name.startsWith("plano-")&&!current())return;stop();exportText=data;Intent i=new Intent(Intent.ACTION_CREATE_DOCUMENT);i.addCategory(Intent.CATEGORY_OPENABLE);i.setType(mime);i.putExtra(Intent.EXTRA_TITLE,name);startActivityForResult(i,501);}
 @Override protected void onActivityResult(int request,int result,Intent data){super.onActivityResult(request,result,data);if(result!=RESULT_OK||data==null||data.getData()==null)return;try{if(request==501){try(OutputStream out=getContentResolver().openOutputStream(data.getData())){if(out==null)throw new IOException("Destino no disponible");out.write(exportText.getBytes(StandardCharsets.UTF_8));}say("Archivo guardado.");}else if(request==502||request==503){ByteArrayOutputStream out=new ByteArrayOutputStream();try(InputStream in=getContentResolver().openInputStream(data.getData())){if(in==null)throw new IOException("Archivo no disponible");byte[] bytes=new byte[2048];int n;while((n=in.read(bytes))!=-1){if(out.size()+n>(request==503?MathTeaching.MAX_BYTES:16000))throw new IOException("El archivo supera el límite permitido");out.write(bytes,0,n);}}String json=new String(out.toByteArray(),StandardCharsets.UTF_8);if(request==503){openTeaching(json);return;}Object parsed=Json.parse(json);if(parsed instanceof Map&&"formas-math-plane-v1".equals(((Map<?,?>)parsed).get("schema"))){Map<String,Object> restored=MathLesson.loadPlane(json);planeKind=((Number)restored.get("plane")).intValue();planeSelect.setSelection(planeKind);x=((Number)restored.get("x")).doubleValue();y=((Number)restored.get("y")).doubleValue();updatePoint();say((String)restored.get("description"));}else{MathLesson imported=MathLesson.load(json);expression.setText(imported.expression);prepare();}}}catch(Exception e){say("No se pudo procesar el archivo: "+e.getMessage());}}
 private final class PlaneCanvas extends View {
  final Paint paint=new Paint(3);float downX,downY;boolean dragged;
  PlaneCanvas(){super(MathActivity.this);setFocusable(true);setFocusableInTouchMode(true);setImportantForAccessibility(View.IMPORTANT_FOR_ACCESSIBILITY_YES);setContentDescription("Lienzo matemático sonoro: "+MathLesson.PLANES[planeKind]+". Desliza para explorar vacío, bordes y figura. Usa también los controles de marco y barrido.");setOnClickListener(v->speak(MathExploration.at(planeKind,canvasPointer)));}
  float scale(){return Math.min(getWidth()/600f,getHeight()/450f);}
  protected void onDraw(Canvas c){super.onDraw(c);c.drawColor(Color.rgb(16,26,32));float s=scale();if(s<=0)return;c.save();c.translate((getWidth()-600*s)/2,(getHeight()-450*s)/2);c.scale(s,s);paint.setStyle(Paint.Style.STROKE);paint.setStrokeWidth(3);paint.setColor(Color.GRAY);c.drawRect(1,1,599,449,paint);int shapeIndex=0;for(Geometry.Shape sh:MathLesson.plane(planeKind).shapes){boolean enabled=touchFilter==0||touchFilter==1&&shapeIndex>=2||touchFilter==2&&shapeIndex<2;shapeIndex++;paint.setColor(enabled?Color.LTGRAY:Color.DKGRAY);Path path=new Path();for(int i=0;i<sh.points.size();i++){Geometry.Point p=sh.points.get(i);if(i==0)path.moveTo((float)p.x,(float)p.y);else path.lineTo((float)p.x,(float)p.y);}if(sh.closed)path.close();c.drawPath(path,paint);if(sh.points.size()==1)c.drawCircle((float)sh.points.get(0).x,(float)sh.points.get(0).y,5,paint);}paint.setStyle(Paint.Style.FILL);paint.setColor(Color.LTGRAY);paint.setTextSize(14);for(int i=-5;i<=5;i++){c.drawText(Integer.toString(i),300+i*40,243,paint);if(i!=0)c.drawText(Integer.toString(i),307,225-i*40,paint);}paint.setColor(Color.CYAN);c.drawCircle((float)canvasPointer.x,(float)canvasPointer.y,6,paint);c.restore();}
  private void sample(float px,float py){float s=scale();if(s<=0)return;Geometry.Point p=new Geometry.Point((px-(getWidth()-600*s)/2)/s,(py-(getHeight()-450*s)/2)/s);if(p.x<0||p.x>600||p.y<0||p.y>450){audio.stop();contactMap.reset();previousContact=null;return;}canvasPointer=p;double oldX=x,oldY=y;if(MathExploration.graduated(p)){x=Math.rint(((p.x-300)/40)*10)/10;y=Math.rint(((225-p.y)/40)*10)/10;}TouchMap.Feedback feedback=contactMap.sample("math:"+planeKind+":"+touchFilter,MathExploration.geometry(planeKind,touchFilter),p,touchSurface,0,mathTolerance,mathAir);boundaryVibration(feedback);boolean voiceBusy=genny.isSpeaking()||voice!=null&&voice.isSpeaking();if(!voiceBusy){if(feedback.kind.equals("silent"))audio.stop();else audio.touch(feedback.position,feedback.kind);}long now=SystemClock.elapsedRealtime();boolean crossing=MathExploration.graduated(p)&&(oldX*x<0||oldY*y<0);if(crossing&&axisMarks!=null&&axisMarks.isChecked()&&now-lastMark>150&&!voiceBusy){lastMark=now;audio.play(new Sound.Program(sound).pulse(p,oldX*x<0?880:440,.08,"vertex"),null);}String description=MathExploration.at(planeKind,p),feature=description.substring(description.indexOf('.')+1);if(announce!=null&&announce.isChecked()&&listening!=null&&listening.getSelectedItemPosition()==1&&!feature.equals(lastFeature)&&now-lastAnnouncement>1200){lastFeature=feature;lastAnnouncement=now;speak(description);}invalidate();if(canvas!=this&&canvas!=null)canvas.invalidate();}
  @Override public void onInitializeAccessibilityNodeInfo(android.view.accessibility.AccessibilityNodeInfo info){super.onInitializeAccessibilityNodeInfo(info);info.setClassName("android.view.View");info.setContentDescription("Lienzo matemático de "+MathLesson.PLANES[planeKind]+". "+MathExploration.at(planeKind,canvasPointer)+". Activa para describir; los botones permiten explorar sin gestos.");}
  @Override public boolean onTouchEvent(MotionEvent e){int action=e.getActionMasked();if(action==MotionEvent.ACTION_DOWN){stop();downX=e.getX();downY=e.getY();dragged=false;getParent().requestDisallowInterceptTouchEvent(true);sample(e.getX(),e.getY());}else if(action==MotionEvent.ACTION_MOVE){dragged|=Math.hypot(e.getX()-downX,e.getY()-downY)>dp(8);sample(e.getX(),e.getY());}else{audio.stop();contactMap.reset();previousContact=null;getParent().requestDisallowInterceptTouchEvent(false);if(action==MotionEvent.ACTION_UP&&!dragged)performClick();}return true;}
  @Override public boolean onHoverEvent(MotionEvent e){int action=e.getActionMasked();if(action==MotionEvent.ACTION_HOVER_ENTER){scanEpoch++;contactMap.reset();previousContact=null;}if(action==MotionEvent.ACTION_HOVER_ENTER||action==MotionEvent.ACTION_HOVER_MOVE)sample(e.getX(),e.getY());else if(action==MotionEvent.ACTION_HOVER_EXIT){audio.stop();contactMap.reset();previousContact=null;}return super.onHoverEvent(e);}
  @Override public boolean onKeyDown(int code,android.view.KeyEvent e){double px=canvasPointer.x,py=canvasPointer.y,step=e.isShiftPressed()?2:10;switch(code){case KeyEvent.KEYCODE_DPAD_LEFT:px-=step;break;case KeyEvent.KEYCODE_DPAD_RIGHT:px+=step;break;case KeyEvent.KEYCODE_DPAD_UP:py-=step;break;case KeyEvent.KEYCODE_DPAD_DOWN:py+=step;break;case KeyEvent.KEYCODE_MOVE_HOME:px=300;py=225;break;case KeyEvent.KEYCODE_SPACE:case KeyEvent.KEYCODE_DPAD_CENTER:performClick();return true;default:return super.onKeyDown(code,e);}float s=scale();sample((float)(Math.max(0,Math.min(600,px))*s+(getWidth()-600*s)/2),(float)(Math.max(0,Math.min(450,py))*s+(getHeight()-450*s)/2));return true;}
  @Override public boolean onKeyUp(int code,KeyEvent e){if(code>=KeyEvent.KEYCODE_DPAD_UP&&code<=KeyEvent.KEYCODE_DPAD_RIGHT){audio.stop();return true;}return super.onKeyUp(code,e);}
 }
 @Override protected void onSaveInstanceState(Bundle out){super.onSaveInstanceState(out);try{captureTeaching();out.putString("teaching",teaching.json());out.putString("editingKey",editingKey);out.putInt("listening",listening.getSelectedItemPosition());}catch(Exception e){say("No se pudo conservar la lección: "+e.getMessage());}out.putString("expression",expression.getText().toString());out.putDouble("x",x);out.putDouble("y",y);out.putInt("plane",planeKind);out.putInt("mode",mode.getSelectedItemPosition());out.putInt("position",position);}
